import {characters,pets,initScene,setCharacters,setBattleMode,attack,renderThumbnails} from './scene.js';
import {shuffle,makeSession,grade,sessionSummary} from './game-core.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const levels=[{id:'village',name:'新手村',note:'先學一招，再出發',crest:'⌂'},{id:'easy',name:'簡單',note:'把任務說清楚',crest:'Ⅰ'},{id:'medium',name:'進階',note:'讓每個條件都到位',crest:'Ⅱ'},{id:'hard',name:'非常難',note:'找出問題，精準修正',crest:'Ⅲ'},{id:'boss',name:'大魔王',note:'三回合・破解複合任務',crest:'♜'}];
const state={audience:'kids',difficulty:'village',character:characters[0],pet:pets[0],bank:[],session:[],index:0,history:[],heroHp:100,enemyHp:100,score:0,hints:2,selected:null,revealed:false,teacher:false,sound:false,streak:0,phase:'setup'};let audio,toastTimer,badges={};try{badges=JSON.parse(localStorage.getItem('prompt-arena-badges')||'{}')}catch{}
function saveBadge(){const s=sessionSummary(state.history);if(s.answered===state.session.length&&s.accuracy>=80){badges[state.audience+'-'+state.difficulty]=true;try{localStorage.setItem('prompt-arena-badges',JSON.stringify(badges))}catch{}}}
function tone(correct){if(!state.sound)return;try{audio??=new AudioContext();audio.resume();for(let i=0;i<3;i++){let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=(correct?[523,659,784]:[262,220,196])[i];g.gain.setValueAtTime(.0001,audio.currentTime+i*.09);g.gain.exponentialRampToValueAtTime(.06,audio.currentTime+i*.09+.01);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+i*.09+.18);o.connect(g).connect(audio.destination);o.start(audio.currentTime+i*.09);o.stop(audio.currentTime+i*.09+.2)}}catch{}}
function renderSetup(){document.querySelectorAll('[data-audience]').forEach(b=>{const yes=b.dataset.audience===state.audience;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',yes)});$('characters').innerHTML=characters.map((c,i)=>`<button class="char ${c.id===state.character.id?'active':''}" data-character="${i}" aria-pressed="${c.id===state.character.id}" aria-label="${c.name}，${c.gender}角色"><canvas data-model="hero" data-index="${i}" aria-hidden="true"></canvas><span>${c.name}</span></button>`).join('');$('pets').innerHTML=pets.map((p,i)=>`<button class="pet ${p.id===state.pet.id?'active':''}" data-pet="${i}" aria-pressed="${p.id===state.pet.id}"><canvas data-model="pet" data-index="${i}" aria-hidden="true"></canvas><span>${p.name}</span></button>`).join('');$('characterLabel').textContent=state.character.name+' · '+state.character.gender;$('petCaption').textContent=state.pet.name+'陪你出發';renderLevels();renderThumbnails()}
function renderLevels(){$('levels').innerHTML=levels.map(l=>{const n=state.bank.filter(q=>q.audience===state.audience&&q.difficulty===l.id).length;return `<button class="level ${l.id===state.difficulty?'active':''}" data-level="${l.id}" aria-pressed="${l.id===state.difficulty}"><span class="crest">${l.crest}</span><span><b>${l.name}${badges[state.audience+'-'+l.id]?' ✦':''}</b><small>${l.note}</small></span><span class="count">${n} 題 ${l.id===state.difficulty?'✓':''}</span></button>`}).join('');$('questionCount').disabled=state.difficulty==='boss';$('questionPicker').innerHTML='<option value="">隨機抽題</option>'+state.bank.filter(q=>q.audience===state.audience&&q.difficulty===state.difficulty&&(q.difficulty!=='boss'||q.round===1)).map(q=>`<option value="${esc(q.id)}">${esc(q.id)} · ${esc(q.title)}</option>`).join('');$('bankStatus').textContent=state.difficulty==='boss'?'每場挑戰一組連續 3 題 · 不必解鎖':'同一場不重複出題 · 答錯也能繼續學習'}
function showPhase(p){state.phase=p;$('setup').hidden=p!=='setup';$('play').hidden=p!=='play';$('result').hidden=p!=='result';$('sceneCaption').hidden=p!=='setup';$('battleHud').hidden=p==='setup';document.body.classList.toggle('in-battle',p!=='setup');setBattleMode(p,state.difficulty);$('sceneHint').textContent=p==='setup'?'拖曳旋轉視角 · 3D 即時場景':'鍵盤 1–4 選答 · Enter 繼續';}
function start(){try{state.session=makeSession(state.bank,{audience:state.audience,difficulty:state.difficulty,count:Number($('questionCount').value),startId:$('questionPicker').value});}catch(e){$('bankStatus').textContent=e.message;return}state.index=0;state.history=[];state.heroHp=100;state.enemyHp=100;state.score=0;state.streak=0;state.hints=2;state.teacher=$('teacherMode').checked;$('heroName').textContent=state.character.name;$('enemyName').textContent=state.difficulty==='boss'?'矛盾大魔王':'迷霧法師';$('location').textContent=levels.find(l=>l.id===state.difficulty).name+'・曙光競技場';showPhase('play');showQuestion();window.scrollTo({top:0,behavior:'smooth'})}
function showQuestion(){const q=state.session[state.index];state.selected=null;state.revealed=false;state.displayOptions=shuffle(q.options);$('scenario').textContent=q.scenario;$('question').textContent=q.question;$('questionMeta').textContent=(state.audience==='kids'?'小朋友':'成人')+' / '+levels.find(l=>l.id===state.difficulty).name+' / '+q.id;$('options').innerHTML=state.displayOptions.map((o,i)=>`<button class="option" data-option="${o.id}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(o.text)}</span></button>`).join('');$('feedback').hidden=true;$('nextBtn').hidden=true;$('hintText').hidden=true;$('hintBtn').disabled=state.hints===0;$('hintCount').textContent=state.hints;$('revealBtn').hidden=true;$('skipBtn').hidden=!state.teacher;$('tutorial').hidden=!q.lesson;if(q.lesson)$('tutorial').textContent=q.lesson;$('roundLabel').textContent=`${state.index+1} / ${state.session.length}`;updateHud();}
function updateHud(){$('heroHp').value=state.heroHp;$('enemyHp').value=state.enemyHp;$('heroHpText').textContent=`${state.heroHp} / 100`;$('enemyHpText').textContent=`${state.enemyHp} / 100`;$('scoreLabel').textContent=`能量 ${state.score}`}
function select(id){if(state.revealed||state.phase!=='play')return;state.selected=id;document.querySelectorAll('.option').forEach(b=>b.classList.toggle('selected',b.dataset.option===id));if(state.teacher){$('revealBtn').hidden=false;return}reveal()}
function reveal(){if(state.revealed||!state.selected)return;const q=state.session[state.index],correct=grade(q,state.selected);state.revealed=true;state.streak=correct?state.streak+1:0;const gained=correct?100+(state.streak>1?20:0):0;state.score+=gained;const damage=Math.ceil(100/state.session.length);if(correct)state.enemyHp=Math.max(0,state.enemyHp-damage);else state.heroHp=Math.max(0,state.heroHp-20);state.history.push({question:q,selected:state.selected,correct,skipped:false});document.querySelectorAll('.option').forEach(b=>{b.disabled=true;b.classList.remove('selected');if(b.dataset.option===q.answer)b.classList.add('correct');else if(b.dataset.option===state.selected)b.classList.add('wrong')});$('revealBtn').hidden=true;$('skipBtn').hidden=true;$('hintBtn').disabled=true;const correctOption=q.options.find(o=>o.id===q.answer),selected=q.options.find(o=>o.id===state.selected);$('feedback').innerHTML=`<h3>${correct?'命中！這個問法更到位。':'差一點！看看關鍵差在哪裡。'}</h3><p><b>最佳問法：</b>${esc(correctOption.text)}</p><p>${esc(q.explanation)}</p>${!correct?`<p><b>你選的問法：</b>${esc(selected.feedback)}</p>`:''}<details><summary>比較四個選項的差異</summary>${state.displayOptions.map((o,i)=>`<p><b>${String.fromCharCode(65+i)}${o.id===q.answer?' · 最佳答案':''}</b>　${esc(o.feedback)}</p>`).join('')}</details>`;$('feedback').hidden=false;$('nextBtn').hidden=false;$('nextBtn').textContent=state.index===state.session.length-1?'查看冒險成果 →':'下一回合 →';$('battleToast').textContent=correct?(state.streak>1?'連擊！ +'+gained:'命中！ +100'):(state.heroHp===0?'繼續練習，重新出發':'護盾受擊 · 再學一招');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('battleToast').textContent='',1600);attack(correct);tone(correct);updateHud()}
function next(){if(!state.revealed)return;if(state.index+1===state.session.length){finish();return}state.index++;showQuestion();$('question').tabIndex=-1;$('question').focus({preventScroll:true});$('play').scrollIntoView({behavior:'smooth',block:'start'})}
function finish(){saveBadge();const s=sessionSummary(state.history);showPhase('result');$('resultTitle').textContent=s.accuracy>=80&&s.answered?'漂亮！你的提問升級了。':'每次修正，都讓問法更進一步。';$('resultSummary').textContent=s.skipped?`本場作答 ${s.answered} 題，老師跳過 ${s.skipped} 題。`:`完成 ${state.session.length} 回合。把今天學到的問法，帶到下一次提問。`;$('resultStats').innerHTML=`<div><b>${s.correct}/${s.answered}</b><span>正確題數</span></div><div><b>${s.accuracy}%</b><span>答對比例</span></div><div><b>${state.score}</b><span>累積能量</span></div>`;$('review').innerHTML=state.history.map((h,i)=>`<details><summary>${h.skipped?'↷':h.correct?'✓':'○'} 第 ${i+1} 題 · ${esc(h.question.title)}</summary><p>${esc(h.question.scenario)}</p><p><b>最佳問法：</b>${esc(h.question.options.find(o=>o.id===h.question.answer).text)}</p><p>${esc(h.question.explanation)}</p></details>`).join('');$('result').scrollIntoView({behavior:'smooth',block:'start'})}
function home(){clearTimeout(toastTimer);$('battleToast').textContent='';showPhase('setup');renderLevels();$('location').textContent='新手村・曙光競技場';window.scrollTo({top:0,behavior:'smooth'})}
$('characters').addEventListener('click',e=>{const b=e.target.closest('[data-character]');if(!b)return;state.character=characters[Number(b.dataset.character)];setCharacters(state.character,state.pet);renderSetup()});$('pets').addEventListener('click',e=>{const b=e.target.closest('[data-pet]');if(!b)return;state.pet=pets[Number(b.dataset.pet)];setCharacters(state.character,state.pet);renderSetup()});document.querySelectorAll('[data-audience]').forEach(b=>b.addEventListener('click',()=>{state.audience=b.dataset.audience;renderSetup()}));$('levels').addEventListener('click',e=>{const b=e.target.closest('[data-level]');if(!b)return;state.difficulty=b.dataset.level;renderLevels();setBattleMode('setup',state.difficulty);$('location').textContent=levels.find(l=>l.id===state.difficulty).name+'・曙光競技場'});$('teacherMode').addEventListener('change',()=>{$('teacherControls').hidden=!$('teacherMode').checked});$('startBtn').addEventListener('click',start);$('options').addEventListener('click',e=>{const b=e.target.closest('[data-option]');if(b)select(b.dataset.option)});$('revealBtn').addEventListener('click',reveal);$('nextBtn').addEventListener('click',next);$('exitBtn').addEventListener('click',home);$('homeBtn').addEventListener('click',home);$('retryBtn').addEventListener('click',start);$('hintBtn').addEventListener('click',()=>{if(state.hints<1||state.revealed)return;state.hints--;$('hintCount').textContent=state.hints;$('hintText').textContent=state.pet.name+'：'+state.session[state.index].hint;$('hintText').hidden=false;$('hintBtn').disabled=true});$('skipBtn').addEventListener('click',()=>{if(!state.teacher||state.revealed)return;state.history.push({question:state.session[state.index],skipped:true,correct:false});state.revealed=true;next()});$('guideBtn').addEventListener('click',()=>$('guide').showModal());$('closeGuide').addEventListener('click',()=>$('guide').close());$('guide').addEventListener('click',e=>{if(e.target===$('guide')){const r=$('guide').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('guide').close()}});$('soundBtn').addEventListener('click',()=>{state.sound=!state.sound;$('soundBtn').setAttribute('aria-pressed',state.sound);$('soundBtn').setAttribute('aria-label',state.sound?'關閉音效':'開啟音效');$('soundBtn').style.color=state.sound?'var(--gold)':'';if(state.sound)tone(true)});
document.addEventListener('keydown',e=>{if(state.phase!=='play'||$('guide').open||e.target.matches('input,select,textarea,summary'))return;if(/^[1-4]$/.test(e.key)){const o=state.displayOptions[Number(e.key)-1];if(o)select(o.id)}if(e.key==='Enter'){e.preventDefault();if(state.revealed)next();else if(state.teacher)reveal()}});
initScene();renderSetup();fetch('/questions.json').then(r=>{if(!r.ok)throw Error('題庫讀取失敗');return r.json()}).then(bank=>{if(!Array.isArray(bank)||!bank.length)throw Error('題庫沒有題目');state.bank=bank;renderLevels();$('startBtn').disabled=false;$('startBtn').innerHTML='開始冒險 <span>→</span>'}).catch(e=>{$('bankStatus').textContent=e.message+'，請重新整理再試一次。';$('startBtn').textContent='題庫尚未就緒';});
